function correctedName(email,name){return correctedNames[String(email||'').trim().toLowerCase()] || String(name||'').trim()}
function normalizeAthlete(a){return {...a,display_name:correctedName(a.email,a.display_name),age_text:normalizeAge(a.age_text),weight_text:normalizeWeight(a.weight_text)}}

const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roundName = (n,total=1) => { const remaining=total-n; if(remaining===0)return 'Final'; if(remaining===1)return 'Meia-final'; if(remaining===2)return 'Quartos de final'; if(remaining===3)return 'Oitavos de final'; return `Ronda ${n}`; };
function matchRoundLabel(m){if(!m.round_number)return '';const total=m.bracket_id?Math.max(1,...matches.filter(x=>x.bracket_id===m.bracket_id).map(x=>x.round_number||1)):m.round_number;return roundName(m.round_number,total)}
function toast(s){const t=$('toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',3800)}
function cfg(){if(APP_CONFIG.url.startsWith('https://') && APP_CONFIG.key && !APP_CONFIG.key.startsWith('COLOCA_AQUI')) return APP_CONFIG;try{return JSON.parse(localStorage.getItem(configKey)||'{}')}catch{return {}}}
function setConnected(s){const el=$('connection');el.innerHTML=`<i></i> ${s?'Ligado à cloud':'Sessão não iniciada'}`;}
function setUI(session){$('setup').classList.add('hidden');$('login').classList.toggle('hidden',!!session);$('app').classList.toggle('hidden',!session);$('recovery').classList.add('hidden');setConnected(!!session);$('who').textContent=session?.user?.email||'';$('sessionEmail').textContent=session?.user?.email||'';if(!session && !cfg().url) $('setup').classList.remove('hidden')}
function showRecovery(){ $('setup').classList.add('hidden');$('login').classList.add('hidden');$('app').classList.add('hidden');$('recovery').classList.remove('hidden');setConnected(false); }
async function init(){let c=cfg();$('url').value=c.url||APP_CONFIG.url||'';$('key').value=c.key||'';if(!c.url||!c.key){$('setup').classList.remove('hidden');$('login').classList.add('hidden');return}try{db=window.supabase.createClient(c.url,c.key);const {data:{session},error}=await db.auth.getSession();if(error)throw error;setUI(session);db.auth.onAuthStateChange((event,s)=>{if(event==='PASSWORD_RECOVERY'){showRecovery();return}setUI(s);if(s){user=s.user;setTimeout(()=>load(),0)}});if(session){user=session.user;await load()}}catch(e){toast('Não foi possível ligar ao Supabase: '+e.message);$('setup').classList.remove('hidden')}}
async function load(){if(!db)return;try{const [a,m]=await Promise.all([db.from('athletes').select('*').order('display_name'),db.from('matches').select('*').order('created_at')]);if(a.error||m.error)throw(a.error||m.error);athletes=(a.data||[]).map(normalizeAthlete);matches=m.data||[];await inferMissingGenders();const unresolved=athletes.some(x=>!normalizeGender(x.gender)&&inferGenderFromName(x.display_name));if(unresolved){const {data:fresh}=await db.from('athletes').select('*').order('display_name');if(fresh)athletes=fresh.map(normalizeAthlete)}render();if(realtime)await db.removeChannel(realtime);realtime=db.channel('icon-live').on('postgres_changes',{event:'*',schema:'public',table:'athletes'},()=>load()).on('postgres_changes',{event:'*',schema:'public',table:'matches'},()=>load()).subscribe()}catch(e){toast(e.message+' — confirma as tabelas, migração e permissões RLS.')}}
function render(){ $('nA').textContent=athletes.length;$('nC').textContent=athletes.filter(x=>x.arrived).length;$('nW').textContent=athletes.filter(x=>x.weighed).length;$('nM').textContent=matches.filter(x=>['called','in_progress'].includes(x.status)).length;renderCheck();renderAthletes();fillAthleteSelects();renderMatchRows();renderQuickCalls();renderQueues();renderPicker();renderBoards();renderBracketOptions();renderSchedule();}
function renderCheck(){const q=$('search').value.toLowerCase();const filtered=athletes.filter(a=>[a.display_name,a.email,a.id,a.team].join(' ').toLowerCase().includes(q));$('checkRows').innerHTML=filtered.map(a=>`<tr><td><button class="athlete-link" onclick="openAthleteCategory('${a.id}')">${esc(a.display_name)}</button><br><small>${esc(a.email||a.id.slice(0,8))}</small></td><td>${esc(a.team||'—')}</td><td>${esc(a.weight_text||'—')}</td><td><input aria-label="Confirmar chegada de ${esc(a.display_name)}" type="checkbox" ${a.arrived?'checked':''} onchange="updateAthlete('${a.id}','arrived',this.checked)"></td><td><input aria-label="Confirmar pesagem de ${esc(a.display_name)}" type="checkbox" ${a.weighed?'checked':''} onchange="updateAthlete('${a.id}','weighed',this.checked)"></td></tr>`).join('');$('checkCards').innerHTML=filtered.map(a=>`<article class="check-card ${a.arrived&&a.weighed?'all-done':''}"><div class="check-card-info"><button class="athlete-link athlete-name-link" onclick="openAthleteCategory('${a.id}')">${esc(a.display_name)}</button><span>${esc(a.team||'Equipa por confirmar')} · ${esc(a.weight_text||'Peso por confirmar')}</span><small>${esc(a.email||a.id.slice(0,8))}</small></div><div class="check-card-actions"><label class="check-toggle ${a.arrived?'is-on':''}"><input type="checkbox" aria-label="Confirmar chegada de ${esc(a.display_name)}" ${a.arrived?'checked':''} onchange="updateAthlete('${a.id}','arrived',this.checked)"><span class="toggle-icon">${a.arrived?'✓':'○'}</span><span>Chegou</span></label><label class="check-toggle ${a.weighed?'is-on':''}"><input type="checkbox" aria-label="Confirmar pesagem de ${esc(a.display_name)}" ${a.weighed?'checked':''} onchange="updateAthlete('${a.id}','weighed',this.checked)"><span class="toggle-icon">${a.weighed?'✓':'⚖'}</span><span>Pesagem</span></label></div></article>`).join('');$('checkEmpty').classList.toggle('hidden',filtered.length>0);$('checkEmpty').textContent=athletes.length?'Não foram encontrados atletas para esta pesquisa.':'Ainda não existem atletas. Importe primeiro o ficheiro CSV.'}
function exportAthletesCSV(){
 if(!athletes.length){toast('Não existem atletas para exportar.');return}
 const headers=['ID','Nome','Email','Equipa','Idade/Escalão','Sexo','Faixa','Peso','Chegou','Pesagem validada'];
 const rows=athletes.map(a=>[a.id,a.display_name,a.email||'',a.team||'',a.age_text||'',a.gender==='M'?'Masculino':a.gender==='F'?'Feminino':'',a.belt||'',a.weight_text||'',a.arrived?'Sim':'Não',a.weighed?'Sim':'Não']);
 const csvCell=value=>{let v=String(value??'');if(/^[=+@]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'};
 const csv='\\ufeff'+[headers,...rows].map(row=>row.map(csvCell).join(';')).join('\\r\\n');
 const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const link=document.createElement('a');const now=new Date();const stamp=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');link.href=url;link.download=`ICON_Atletas_atualizados_${stamp}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast(`CSV exportado com ${athletes.length} atletas.`)
}

function renderAthletes(){refreshAthleteFilters();const term=($('athleteSearch')?.value||'').toLowerCase().trim();const ageFilter=$('athleteAgeFilter')?.value||'',beltFilter=$('athleteBeltFilter')?.value||'',teamFilter=$('athleteTeamFilter')?.value||'';const list=athletes.filter(a=>[a.display_name,a.email,a.team,a.belt,a.age_text,a.weight_text].join(' ').toLowerCase().includes(term)&&(!ageFilter||ageGroup(a.age_text)===ageFilter)&&(!beltFilter||String(a.belt||'').toLowerCase()===beltFilter)&&(!teamFilter||String(a.team||'')===teamFilter));$('athleteRows').innerHTML=list.map(a=>`<tr><td><span class="state-tag">${esc(a.id.slice(0,8))}</span></td><td><button class="athlete-link athlete-name-link" onclick="openAthleteCategory('${a.id}')">${esc(a.display_name)}</button><br><small>${esc(a.email||'sem email')}</small></td><td>${esc(a.team||'—')}</td><td>${esc(a.age_text||'—')}</td><td>${esc(a.gender==='M'?'Masculino':a.gender==='F'?'Feminino':'—')}</td><td>${esc(a.belt||'—')}</td><td>${esc(a.weight_text||'—')}</td><td><span class="state-tag ${a.arrived?'ok':''}">${a.arrived?'Chegou':'Por chegar'}${a.weighed?' · Pesado':''}</span><br><button class="button-light small athlete-edit-button" type="button" onclick="editAthlete('${a.id}')">✎ Editar</button> <button class="button-danger small" type="button" onclick="deleteAthlete(\'${a.id}\')">Eliminar</button></td></tr>`).join('');$('athleteCards').innerHTML=list.map(a=>`<article class="athlete-mobile-card"><div class="athlete-mobile-main"><button class="athlete-link athlete-name-link" onclick="openAthleteCategory('${a.id}')">${esc(a.display_name)}</button><small>${esc(a.team||'Equipa por confirmar')} · ${esc(a.belt||'Faixa por confirmar')}</small><small>${esc(a.age_text||'Idade por confirmar')} · ${esc(a.weight_text||'Peso por confirmar')}</small>${a.email?`<small class="athlete-email">${esc(a.email)}</small>`:''}</div><div class="athlete-mobile-bottom"><span class="state-tag ${a.arrived?'ok':''}">${a.arrived?'Chegou':'Por chegar'}${a.weighed?' · Pesado':''}</span><div class="athlete-mobile-actions"><button class="primary athlete-edit-button" type="button" onclick="editAthlete(\'${a.id}\')">Editar</button><button class="button-danger" type="button" onclick="deleteAthlete(\'${a.id}\')">Eliminar</button></div></div></article>`).join('');$('athleteEmpty').classList.toggle('hidden',list.length>0);$('athleteEmpty').textContent=athletes.length?'Não foram encontrados atletas.':'Ainda não existem inscrições importadas.'}

function normalizeGender(value){const v=String(value||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().trim();if(['m','masculino','homem','male','man','rapaz'].includes(v))return 'M';if(['f','feminino','mulher','female','woman','rapariga'].includes(v))return 'F';return ''}
// Inferência conservadora pelo primeiro nome: só preenche nomes comuns e relativamente inequívocos.
function inferGenderFromName(name){
 const first=String(name||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().trim().split(/\\s+/)[0].replace(/[^a-z-]/g,'');
 const male=new Set('afonso alberto alexandre andre antonio arthur augusto bruno caio carlos daniel diogo duarte eduardo fabio francisco gabriel goncalo gustavo henrique hugo joao jose leandro leonardo lourenco lucas manuel marcelo marco martim mateus miguel nuno pedro rodrigo rui samuel tiago tomas vasco vicente'.split(' '));
 const female=new Set('ana beatriz benedita bruna carolina catarina clara constanca ines joana julia khyara laura leticia luana lucia mafalda maria matilde melissa marta rita sara sofia vanessa victoria'.split(' '));
 if(male.has(first))return 'M';if(female.has(first))return 'F';return '';
}
async function inferMissingGenders(){
 const candidates=athletes.filter(a=>!normalizeGender(a.gender)&&a.display_name);
 for(const a of candidates){const inferred=inferGenderFromName(a.display_name);if(!inferred)continue;
  const {error}=await db.from('athletes').update({gender:inferred}).eq('id',a.id).is('gender',null);
  if(error)console.warn('Não foi possível inferir sexo para',a.display_name,error.message);
 }
}
function isAdultAthlete(a){const n=Number(normalizeAge(a?.age_text).replace(',','.'));return Number.isFinite(n)&&n>=18}
function adultMatchGenderIssue(a,b){if(!a||!b||(!isAdultAthlete(a)&&!isAdultAthlete(b)))return '';if(!isAdultAthlete(a)||!isAdultAthlete(b))return 'Não é permitido misturar um atleta adulto com um atleta de escalão não adulto.';const ga=normalizeGender(a.gender),gb=normalizeGender(b.gender);if(!ga||!gb)return 'Indique o sexo de ambos os atletas adultos antes de criar o combate.';if(ga!==gb)return 'Combate bloqueado: nos adultos não são permitidos confrontos entre homens e mulheres.';return ''}
function ageGroup(value){const n=Number(normalizeAge(value).replace(',','.'));if(!Number.isFinite(n))return 'sem-idade';if(n<=6)return '4-6';if(n<=9)return '7-9';if(n<=12)return '10-12';if(n<=15)return '13-15';return '16+'}
function refreshAthleteFilters(){const set=(id,values,placeholder)=>{const el=$(id);if(!el)return;const old=el.value;el.innerHTML=`<option value="">${placeholder}</option>`+values.map(v=>`<option value="${esc(v.value)}">${esc(v.label)}</option>`).join('');el.value=old};set('athleteAgeFilter',[{value:'4-6',label:'4–6 anos'},{value:'7-9',label:'7–9 anos'},{value:'10-12',label:'10–12 anos'},{value:'13-15',label:'13–15 anos'},{value:'16+',label:'16+ anos'},{value:'sem-idade',label:'Idade por confirmar'}],'Todas as idades');set('athleteBeltFilter',[...new Set(athletes.map(a=>String(a.belt||'').trim()).filter(Boolean).map(v=>({value:v.toLowerCase(),label:v})))].sort((a,b)=>a.label.localeCompare(b.label)),'Todas as faixas');set('athleteTeamFilter',[...new Set(athletes.map(a=>String(a.team||'').trim()).filter(Boolean).map(v=>({value:v,label:v})))].sort((a,b)=>a.label.localeCompare(b.label)),'Todas as equipas')}
async function deleteAthlete(id){const a=athletes.find(x=>x.id===id);if(!a)return;const used=matches.some(m=>m.fighter_a_id===id||m.fighter_b_id===id);if(!confirm(`Eliminar "${a.display_name}"? Esta ação não pode ser desfeita.${used?' ATENÇÃO: o atleta aparece em combates; reveja os quadros depois.':''}`))return;try{const {error}=await db.from('athletes').delete().eq('id',id);if(error)throw error;toast('Atleta eliminado. Reveja os combates associados.');await load()}catch(e){toast('Não foi possível eliminar: '+e.message)}}

function openAthleteForm(id=null){const a=id?athletes.find(x=>x.id===id):null;$('athleteForm').reset();$('athleteEditId').value=a?.id||'';$('athleteFormTitle').textContent=a?'Editar atleta':'Adicionar atleta';$('saveAthlete').textContent=a?'Guardar alterações':'Guardar atleta';$('athleteFormMsg').textContent='';$('athleteName').value=a?.display_name||'';$('athleteEmail').value=a?.email||'';$('athleteTeam').value=a?.team||'';$('athleteAge').value=a?.age_text||'';$('athleteBelt').value=a?.belt||'';$('athleteWeight').value=a?.weight_text||'';$('athleteGender').value=normalizeGender(a?.gender);$('athleteFormPanel').classList.remove('hidden');document.body.classList.add('athlete-form-open');$('athleteFormPanel').scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>$('athleteName').focus(),150)}
function editAthlete(id){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='athletes'));document.querySelectorAll('.pane').forEach(x=>x.classList.toggle('hidden',x.id!=='athletes'));openAthleteForm(id)}
function closeAthleteForm(){$('athleteFormPanel').classList.add('hidden');document.body.classList.remove('athlete-form-open');$('athleteFormMsg').textContent=''}
async function saveAthleteForm(e){
 e.preventDefault();const id=$('athleteEditId').value,name=$('athleteName').value.trim();const autoAssign=!id&&$('autoAssignBracket')?.checked;
 if(!name){$('athleteFormMsg').textContent='O nome do atleta é obrigatório.';return}
 const email=$('athleteEmail').value.trim(),typedGender=normalizeGender($('athleteGender').value);
 const payload={display_name:name,email:email||null,team:$('athleteTeam').value.trim()||null,age_text:normalizeAge($('athleteAge').value)||null,belt:$('athleteBelt').value.trim()||null,weight_text:normalizeWeight($('athleteWeight').value)||null,gender:typedGender||inferGenderFromName(name)||null};
 $('saveAthlete').disabled=true;$('athleteFormMsg').textContent='A guardar na cloud…';
 try{
  let query;
  if(id){query=await db.from('athletes').update(payload).eq('id',id)}else{query=await db.from('athletes').insert(payload).select('id').single()}
  if(query.error)throw query.error;
  const athleteId=id||query.data?.id;
  if(id){
   const linkedA=await db.from('matches').update({fighter_a_name:name}).eq('fighter_a_id',id);if(linkedA.error)throw linkedA.error;
   const linkedB=await db.from('matches').update({fighter_b_name:name}).eq('fighter_b_id',id);if(linkedB.error)throw linkedB.error;
   const linkedWinner=await db.from('matches').update({winner_name:name}).eq('winner_id',id);if(linkedWinner.error)throw linkedWinner.error;
  }
  $('athleteFormMsg').textContent=id?'Alterações guardadas em todas as páginas e combates associados.':'Atleta adicionado à lista.';
  toast(id?'Atleta atualizado em toda a aplicação.':'Atleta adicionado.');closeAthleteForm();await load();
  if(autoAssign&&athleteId)await autoPrepareBracket(athleteId);
 }catch(err){$('athleteFormMsg').textContent='Não foi possível guardar: '+err.message;toast('Erro ao guardar atleta.')}
 finally{$('saveAthlete').disabled=false}
}
function fillAthleteSelects(){['a','b'].forEach(id=>{const old=$(id).value;$(id).innerHTML='<option value="">Escolher atleta…</option>'+athletes.map(a=>`<option value="${a.id}">${esc(a.display_name)} — ${esc(a.id.slice(0,8))}</option>`).join('');$(id).value=old})}
function statusLabel(s){return({pending:'Por chamar',called:'Atletas chamados',in_progress:'A decorrer',waiting:'Em espera',completed:'Concluído',cancelled:'Cancelado'})[s]||s}
function renderMatchRows(){const q=($('matchSearch')?.value||'').toLowerCase();$('matchRows').innerHTML=matches.filter(m=>[m.match_code,m.category,m.fighter_a_name,m.fighter_b_name,m.winner_name].join(' ').toLowerCase().includes(q)).map(m=>`<tr id="match-row-${m.id}"><td><span class="state-tag">${esc(m.match_code||m.id.slice(0,8))}</span></td><td>${esc(m.category)}${m.round_number?`<br><small>${esc(matchRoundLabel(m))}</small>`:''}</td><td>Tatame ${m.mat||'—'}</td><td>${esc(m.fighter_a_name)} <small>vs.</small> ${esc(m.fighter_b_name)}</td><td><span class="state-tag ${m.status==='completed'?'ok':''}">${statusLabel(m.status)}</span></td><td>${esc(m.winner_name||'—')}</td><td class="row-actions"><button class="button-light small" onclick="editMatch('${m.id}')">Editar</button>${m.status==='completed'?`<button class="button-warning small" onclick="voidResult('${m.id}')">Anular resultado</button>`:''}${['cancelled','waiting'].includes(m.status)?`<button class="button-light small" onclick="setStatus('${m.id}','pending')">${m.status==='waiting'?'Voltar à fila':'Reabrir'}</button>`:`<button class="button-light small" onclick="setStatus('${m.id}','cancelled')">Cancelar</button>`}<button class="button-danger small" onclick="deleteMatch('${m.id}')">Apagar</button></td></tr>`).join('')}
async function editMatch(id){const m=matches.find(x=>x.id===id);if(!m)return;const category=prompt('Categoria:',m.category||'');if(category===null)return;if(!category.trim()){toast('A categoria não pode ficar vazia.');return}const matRaw=prompt('Tatame (1 ou 2):',String(m.mat||1));if(matRaw===null)return;const mat=Number(matRaw);if(![1,2].includes(mat)){toast('O tatame tem de ser 1 ou 2.');return}const nameA=prompt('Nome do atleta A:',m.fighter_a_name||'');if(nameA===null)return;const nameB=prompt('Nome do atleta B:',m.fighter_b_name||'');if(nameB===null)return;const status=prompt('Estado: pending, called, in_progress, completed ou cancelled',m.status||'pending');if(status===null)return;if(!['pending','called','in_progress','completed','cancelled'].includes(status)){toast('Estado inválido.');return}let payload={category:category.trim(),mat,fighter_a_name:nameA.trim()||'A aguardar atleta',fighter_b_name:nameB.trim()||'A aguardar atleta',status};if(status==='completed'){const choice=prompt(`Vencedor? Escreva A ou B.
A: ${nameA}
B: ${nameB}`,m.winner_id===m.fighter_b_id?'B':'A');if(choice===null)return;if(!['A','B','a','b'].includes(choice)){toast('Escolha A ou B.');return}const side=choice.toLowerCase();payload.winner_id=side==='a'?m.fighter_a_id:m.fighter_b_id;payload.winner_name=side==='a'?nameA.trim():nameB.trim();payload.completed_at=new Date().toISOString()}else{payload.winner_id=null;payload.winner_name=null;payload.completed_at=null}if(!confirm('Guardar as correções deste combate? Se pertencer a um quadro, reveja manualmente as rondas seguintes.'))return;const {error}=await db.from('matches').update(payload).eq('id',id);if(error){toast('Não foi possível guardar: '+error.message);return}toast('Combate corrigido. Reveja a progressão do quadro, se aplicável.');await load()}
async function clearAdvancedWinner(m){if(!m?.next_match_id||!m.winner_id)return;const next=matches.find(x=>x.id===m.next_match_id);if(!next)return;const slot=m.next_slot==='B'?'b':'a',idKey=slot==='a'?'fighter_a_id':'fighter_b_id',nameKey=slot==='a'?'fighter_a_name':'fighter_b_name';if(next[idKey]!==m.winner_id)return;if(next.status==='completed'&&next.winner_id){await clearAdvancedWinner(next)}const payload={[idKey]:null,[nameKey]:'A aguardar atleta'};if(next.status==='completed'||next.status==='in_progress'||next.status==='called')Object.assign(payload,{status:'pending',winner_id:null,winner_name:null,completed_at:null});const {error}=await db.from('matches').update(payload).eq('id',next.id);if(error)throw error}
async function voidResult(id){const m=matches.find(x=>x.id===id);if(!m||m.status!=='completed')return;if(!confirm(`Anular o resultado de ${m.match_code||m.id.slice(0,8)}? O vencedor será retirado da ronda seguinte e os combates dependentes serão reabertos automaticamente, quando necessário.`))return;try{await clearAdvancedWinner(m);const {error}=await db.from('matches').update({status:'pending',winner_id:null,winner_name:null,completed_at:null}).eq('id',id);if(error)throw error;toast('Resultado anulado e progressão da chave atualizada.');await load()}catch(e){toast('Não foi possível atualizar toda a chave: '+e.message);await load()}}
async function deleteMatch(id){const m=matches.find(x=>x.id===id);if(!m)return;if(!confirm(`Apagar definitivamente o combate ${m.match_code||m.id.slice(0,8)}? Esta ação não pode ser desfeita. Se pertencer a um quadro, confirme as ligações às rondas seguintes.`))return;const {error}=await db.from('matches').delete().eq('id',id);if(error){toast('Erro ao apagar combate: '+error.message);return}toast('Combate apagado.');await load()}
function localDateTimeValue(d){const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function fmtTime(d){return d.toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'})}
function renderSchedule(){if(!$('schedulePanels'))return;const startRaw=$('scheduleStart').value;const start=startRaw?new Date(startRaw):new Date();const per=Math.max(1,Number($('fightMinutes').value)||6),change=Math.max(0,Number($('changeoverMinutes').value)||0),breakM=Math.max(0,Number($('breakMinutes').value)||0);const active=matches.filter(m=>!['completed','cancelled'].includes(m.status));const mats={1:[],2:[]};let unassigned=0;active.forEach(m=>{let mat=Number(m.mat);if(![1,2].includes(mat)){mat=(mats[1].length<=mats[2].length)?1:2;unassigned++}mats[mat].push(m)});for(const n of [1,2])mats[n].sort((a,b)=>{const statusRank=x=>x.status==='in_progress'?0:x.status==='called'?1:2;return statusRank(a)-statusRank(b)||(a.round_number||0)-(b.round_number||0)||(a.created_at||'').localeCompare(b.created_at||'')});let maxEnd=new Date(start);let total=0;$('schedulePanels').innerHTML=[1,2].map(n=>{let cursor=new Date(start);const list=mats[n];const cards=list.map((m,i)=>{if(i>0){cursor=new Date(cursor.getTime()+(change+(i%10===0?breakM:0))*60000)}const begin=new Date(cursor);cursor=new Date(cursor.getTime()+per*60000);total++;return `<article class="schedule-bout ${m.status==='in_progress'?'active':''}"><div class="schedule-time">${fmtTime(begin)} <span>–</span> ${fmtTime(cursor)}</div><div class="schedule-bout-main"><strong>${esc(m.match_code||m.id.slice(0,8))} · ${esc(m.category||'Sem categoria')}</strong><small>${esc(m.fighter_a_name||'A aguardar atleta')} vs. ${esc(m.fighter_b_name||'A aguardar atleta')}</small></div><span class="state-tag">${statusLabel(m.status)}</span></article>`}).join('');if(cursor>maxEnd)maxEnd=cursor;return `<div class="tatami schedule-tatami"><div class="tatami-head"><h3>Tatame ${n}</h3><small>${list.length} combate(s) estimados</small></div>${cards||'<p class="empty-state">Sem combates por concluir.</p>'}<div class="schedule-end">Fim estimado: <strong>${list.length?fmtTime(cursor):'—'}</strong></div></div>`}).join('');$('scheduleSummary').textContent=total?`${total} combates por concluir · fim estimado do evento: ${fmtTime(maxEnd)}${unassigned?` · ${unassigned} combate(s) sem tatame distribuídos provisoriamente`:''}`:'Não há combates pendentes para estimar.'}
function tickClock(){const el=$('liveClock');if(el)el.textContent=new Date().toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function renderQuickCalls(){
 const root=$('quickCallPanels'); if(!root)return;
 const completed=matches.filter(m=>m.status==='completed').sort((a,b)=>String(b.completed_at||'').localeCompare(String(a.completed_at||'')));
 const upcomingTotal=matches.filter(m=>['pending','called','in_progress','waiting'].includes(m.status)).length;
 $('upcomingCountNav').textContent=upcomingTotal; $('completedCountNav').textContent=completed.length;
 if($('upcomingCount'))$('upcomingCount').textContent=upcomingTotal; if($('completedCount'))$('completedCount').textContent=completed.length;
 $('completedPanels').innerHTML=completed.length?completed.map(m=>`<article class="completed-bout"><div><span class="qc-kicker">${esc(m.match_code||'Combate')} · Tatame ${m.mat||'—'}</span><h4>${esc(m.category||'Sem categoria')}</h4><p>${esc(m.fighter_a_name||'Atleta por definir')} <b>vs.</b> ${esc(m.fighter_b_name||'Atleta por definir')}</p></div><div class="completed-result"><span>VENCEDOR</span><strong>${esc(m.winner_name||'Resultado não registado')}</strong><small>${m.completed_at?new Date(m.completed_at).toLocaleTimeString('pt-PT',{hour:'2-digit',minute:'2-digit'}):''}</small></div><button class="button-light small" onclick="focusMatch('${m.id}')">Ver combate</button></article>`).join(''):'<p class="empty-state">Ainda não existem combates concluídos.</p>';
 root.innerHTML=[1,2].map(mat=>{
  const pool=matches.filter(m=>Number(m.mat)===mat&&!['completed','cancelled','waiting'].includes(m.status)).sort((a,b)=>(a.status==='in_progress'?-1:b.status==='in_progress'?1:a.status==='called'?-1:b.status==='called'?1:0)||(a.round_number||0)-(b.round_number||0)||String(a.match_code||'').localeCompare(String(b.match_code||''),undefined,{numeric:true})||(a.created_at||'').localeCompare(b.created_at||''));
  const active=pool.find(m=>m.status==='in_progress'); const called=pool.find(m=>m.status==='called'); const pending=pool.filter(m=>m.status==='pending'); const next=pending[0];
  const waiting=matches.filter(m=>Number(m.mat)===mat&&m.status==='waiting');
  const bout=(m,empty)=>m?`<div class="qc-match"><div class="qc-match-top"><strong>${esc(m.match_code||'Combate')}</strong><span class="qc-category">${esc(m.category||'Sem categoria')}</span></div><div class="qc-athletes"><button class="athlete-link" onclick="openAthleteCategory('${m.fighter_a_id||''}')">${esc(m.fighter_a_name||'Atleta por definir')}</button><b>VS</b><button class="athlete-link" onclick="openAthleteCategory('${m.fighter_b_id||''}')">${esc(m.fighter_b_name||'Atleta por definir')}</button></div></div>`:`<div class="qc-empty">${empty}</div>`;
  let action='';
  if(!active&&called){action=`<button class="qc-primary" onclick="setStatus('${called.id}','in_progress')"><span>▶</span><span><b>Iniciar combate</b><small>Os atletas já foram chamados</small></span></button>`}
  else if(!active&&!called&&next){action=`<button class="qc-primary" onclick="setStatus('${next.id}','called')"><span>📣</span><span><b>Chamar combate</b><small>Enviar os atletas para o tatame</small></span></button>`}
  else if(active&&called){action=`<div class="qc-note"><b>Próximo combate já chamado</b><span>Termine o combate atual antes de iniciar o seguinte.</span></div>`}
  else if(active&&next){action=`<button class="qc-secondary" onclick="setStatus('${next.id}','called')"><span>📣</span><span><b>Chamar o seguinte</b><small>O combate atual continua a decorrer</small></span></button>`}
  else if(!active&&!called&&!next){action=`<div class="qc-note"><b>Fila sem combates prontos</b><span>Veja os combates em espera abaixo ou aguarde novos combates.</span></div>`}
  return `<section class="qc-mat"><header class="qc-head"><div><span class="qc-kicker">DIREÇÃO DE PROVA</span><h3>Tatame ${mat}</h3></div><span class="qc-count">${pending.length} por chamar</span></header><div class="qc-step qc-live"><div class="qc-step-label"><span class="qc-number">1</span><span>A DECORRER</span><i></i></div>${bout(active,'Nenhum combate a decorrer.')}${active?`<div class="qc-result"><button onclick="finish('${active.id}','a')">Vence ${esc(shortName(active.fighter_a_name))}</button><button onclick="finish('${active.id}','b')">Vence ${esc(shortName(active.fighter_b_name))}</button></div><button class="qc-reset" onclick="resetStartedMatch('${active.id}')">↶ Reset · desfazer início</button>`:''}</div><div class="qc-step qc-next"><div class="qc-step-label"><span class="qc-number">2</span><span>${called?'CHAMADO · À ESPERA':'A SEGUIR'}</span><i></i></div>${bout(called||next,'A fila está vazia.')}${called?`<div class="qc-inline-actions"><button class="button-light small" onclick="setStatus('${called.id}','waiting')">Colocar em espera</button><button class="button-light small" onclick="setStatus('${called.id}','pending')">Retirar chamada</button></div>`:''}</div><div class="qc-action-area">${action}</div>${waiting.length?`<div class="qc-waiting"><h4>Em espera (${waiting.length})</h4>${waiting.map(m=>`<div class="qc-wait-row"><span><b>${esc(m.match_code||'Combate')}</b> · ${esc(m.fighter_a_name)} vs. ${esc(m.fighter_b_name)}</span><button class="button-light small" onclick="setStatus('${m.id}','pending')">Voltar à fila</button></div>`).join('')}</div>`:''}<div class="qc-footnote">Fluxo: chamar → iniciar → registar vencedor. Se um atleta não responder, coloque o combate em espera.</div></section>`;
 }).join('');
}
function switchQuickTab(tab){document.querySelectorAll('.quick-tab').forEach(b=>b.classList.toggle('active',b.dataset.qtab===tab));$('quickUpcoming').classList.toggle('hidden',tab!=='upcoming');$('quickCompleted').classList.toggle('hidden',tab!=='completed')}
function openAthleteCategory(id){
 if(!id){toast('Este atleta ainda não está associado a uma inscrição.');return}
 const athlete=athletes.find(a=>String(a.id)===String(id));
 if(!athlete){toast('Não foi possível encontrar este atleta. Atualize a lista e tente novamente.');return}
 const athleteMatches=matches.filter(m=>String(m.fighter_a_id)===String(id)||String(m.fighter_b_id)===String(id));
 const categories=[...new Set(athleteMatches.map(m=>String(m.category||'Sem categoria')).filter(Boolean))];
 if(!categories.length){showAthleteCategoryModal(athlete,[],null);return}
 if(categories.length===1){showAthleteCategoryModal(athlete,athleteMatches,categories[0]);return}
 showAthleteCategoryChooser(athlete,athleteMatches,categories);
}
function showAthleteCategoryChooser(athlete,athleteMatches,categories){
 let modal=document.getElementById('athleteCategoryModal');
 if(!modal){modal=document.createElement('div');modal.id='athleteCategoryModal';modal.className='athlete-modal-backdrop';modal.onclick=e=>{if(e.target===modal)modal.remove()};document.body.appendChild(modal)}
 modal.innerHTML=`<section class="athlete-modal"><button class="modal-close" onclick="document.getElementById('athleteCategoryModal').remove()">✕</button><span class="section-kicker">PERCURSO DO ATLETA</span><h2>${esc(athlete.display_name)}</h2><p>Este atleta está inscrito em várias categorias. Escolha a chave que pretende consultar.</p><div class="athlete-category-choices">${categories.map((c,i)=>`<button class="button-light athlete-category-choice" type="button" onclick="chooseAthleteCategory('${athlete.id}',${i})"><strong>${esc(c)}</strong><small>${athleteMatches.filter(m=>(m.category||'Sem categoria')===c).length} combate(s)</small></button>`).join('')}</div></section>`;
 modal._athleteCategoryData={athlete,athleteMatches,categories};
}
function chooseAthleteCategory(id,index){const modal=document.getElementById('athleteCategoryModal');const data=modal?modal._athleteCategoryData:null;if(!data||String(data.athlete.id)!==String(id))return;const category=data.categories[index];showAthleteCategoryModal(data.athlete,data.athleteMatches.filter(m=>(m.category||'Sem categoria')===category),category)}
function showAthleteCategoryModal(athlete,list,category){let modal=document.getElementById('athleteCategoryModal');if(!modal){modal=document.createElement('div');modal.id='athleteCategoryModal';modal.className='athlete-modal-backdrop';modal.onclick=e=>{if(e.target===modal)modal.remove()};document.body.appendChild(modal)}modal.innerHTML=`<section class="athlete-modal"><button class="modal-close" onclick="document.getElementById('athleteCategoryModal').remove()">✕</button><span class="section-kicker">PERCURSO DO ATLETA</span><h2>${esc(athlete.display_name)}</h2><p>${esc(category||'Sem categoria associada')}</p><div class="athlete-category-meta">${esc([athlete.age_text,athlete.belt,athlete.weight_text,athlete.team].filter(Boolean).join(' · '))}</div><h3>Combates desta categoria</h3>${list.length?list.sort((a,b)=>(a.round_number||0)-(b.round_number||0)).map(m=>`<article class="athlete-category-bout"><div><strong>${esc(m.match_code||'Combate')} · ${esc(statusLabel(m.status))}</strong><p>${esc(m.fighter_a_name)} vs. ${esc(m.fighter_b_name)}</p>${m.winner_name?`<small>Vencedor: ${esc(m.winner_name)}</small>`:''}</div><button class="button-light small" onclick="document.getElementById('athleteCategoryModal').remove();focusMatch('${m.id}')">Abrir</button></article>`).join(''):'<p class="empty-state">Não há combates registados para este atleta.</p>'}</section>`;modal.classList.remove('hidden')}
function focusMatch(id){const m=matches.find(x=>x.id===id);if(!m)return;const tab=document.querySelector('[data-tab="matches"]');if(tab)tab.click();const search=$('matchSearch');if(search){search.value=m.match_code||'';renderMatchRows()}requestAnimationFrame(()=>{const row=document.getElementById('match-row-'+id);if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.add('focus-match-row');setTimeout(()=>row.classList.remove('focus-match-row'),3000)}else{const table=document.getElementById('matchRows');if(table)table.scrollIntoView({behavior:'smooth',block:'start'})}})}
function renderQueues(){const active=matches.filter(m=>!['completed','cancelled','waiting'].includes(m.status));const unassigned=active.filter(m=>![1,2].includes(Number(m.mat)));$('matPanels').innerHTML=[1,2].map(n=>{const ms=active.filter(m=>Number(m.mat)===n||(n===1&&![1,2].includes(Number(m.mat)))).sort((a,b)=>(a.status==='in_progress'?-1:b.status==='in_progress'?1:a.status==='called'?-1:b.status==='called'?1:0)||(a.round_number||0)-(b.round_number||0));return `<div class="tatami"><div class="tatami-head"><h3>Tatame ${n}</h3><small>${ms.length} combate(s) por concluir${n===1&&unassigned.length?' · inclui combate(s) sem tatame':''}</small></div>${ms.length?ms.map(m=>`<article class="bout ${m.status==='in_progress'?'active':''}"><div class="bout-title"><strong>${esc(m.match_code||m.id.slice(0,8))} · ${esc(m.category||'Sem categoria')}</strong><span class="state-tag">${statusLabel(m.status)}</span></div><p><strong>${esc(m.fighter_a_name||'Atleta por definir')}</strong><span class="versus">VS</span><strong>${esc(m.fighter_b_name||'Atleta por definir')}</strong></p>${![1,2].includes(Number(m.mat))?'<small class="unassigned-note">Tatame por atribuir</small>':''}<div class="bout-actions">${m.status==='pending'?`<button class="primary" onclick="setStatus('${m.id}','called')">Chamar atletas</button>`:''}${m.status==='called'?`<button class="primary" onclick="setStatus('${m.id}','in_progress')">Iniciar combate</button><button class="button-light" onclick="setStatus('${m.id}','waiting')">Colocar em espera</button>`:''}${m.status==='in_progress'?`<button class="primary" onclick="finish('${m.id}','a')">Vence ${esc(shortName(m.fighter_a_name))}</button><button class="button-light" onclick="finish('${m.id}','b')">Vence ${esc(shortName(m.fighter_b_name))}</button><button class="button-warning small" onclick="resetStartedMatch('${m.id}')">Reset</button>`:''}</div></article>`).join(''):'<p class="empty-state">Sem combates pendentes neste tatame.</p>'}</div>`}).join('')}
function shortName(n){return String(n||'Atleta').split(' ').slice(0,2).join(' ')}
async function updateAthlete(id,k,v){const {error}=await db.from('athletes').update({[k]:v}).eq('id',id);if(error)toast(error.message);else{toast('Atualizado e sincronizado');await load()}}
async function setStatus(id,status){const m=matches.find(x=>x.id===id);if(!m)return;if(status==='cancelled'&&m.status==='completed'){if(!confirm('Este combate já tem resultado. Anular o resultado e cancelar o combate? A chave será recalculada.'))return;try{await clearAdvancedWinner(m);const {error}=await db.from('matches').update({status:'cancelled',winner_id:null,winner_name:null,completed_at:null}).eq('id',id);if(error)throw error;toast('Combate cancelado e chave atualizada.');await load()}catch(e){toast('Erro ao atualizar a chave: '+e.message);await load()}return}if(status==='cancelled'&&m.winner_id){try{await clearAdvancedWinner(m)}catch(e){toast('Erro ao corrigir a progressão: '+e.message);return}}const {error}=await db.from('matches').update({status,winner_id:status==='cancelled'?null:m.winner_id,winner_name:status==='cancelled'?null:m.winner_name,completed_at:status==='cancelled'?null:m.completed_at}).eq('id',id);if(error)toast(error.message);else await load()}
async function resetStartedMatch(id){const m=matches.find(x=>x.id===id);if(!m||m.status!=='in_progress')return;if(!confirm(`Desfazer o início do combate ${m.match_code||''}? O combate voltará a “Atletas chamados”, sem apagar atletas nem resultados.`))return;const {error}=await db.from('matches').update({status:'called',winner_id:null,winner_name:null,completed_at:null}).eq('id',id).eq('status','in_progress');if(error){toast('Não foi possível repor o estado: '+error.message);return}toast('Início desfeito. O combate voltou a “Atletas chamados”.');await load()}
async function finish(id,side){const m=matches.find(x=>x.id===id);if(!m)return;const winnerId=side==='a'?m.fighter_a_id:m.fighter_b_id;const name=side==='a'?m.fighter_a_name:m.fighter_b_name;if(!winnerId){toast('Este lugar ainda não tem atleta atribuído.');return}if(!confirm(`Confirmar vitória de ${name}?${m.next_match_id?' O atleta avança automaticamente para a ronda seguinte.':''}`))return;const {error}=await db.from('matches').update({status:'completed',winner_id:winnerId,winner_name:name,completed_at:new Date().toISOString()}).eq('id',id);if(error){toast(error.message);return}if(m.next_match_id){const next=matches.find(x=>x.id===m.next_match_id);if(next){const slot=m.next_slot==='B'?'b':'a';const payload=slot==='a'?{fighter_a_id:winnerId,fighter_a_name:name}:{fighter_b_id:winnerId,fighter_b_name:name};const up=await db.from('matches').update(payload).eq('id',next.id);if(up.error){toast('Resultado guardado, mas não foi possível avançar o vencedor: '+up.error.message);await load();return}await maybeAutoBye(next.id)}}toast('Resultado guardado'+(m.next_match_id?' e vencedor avançado.':'.'));await load()}
async function maybeAutoBye(matchId){const {data:m,error}=await db.from('matches').select('*').eq('id',matchId).single();if(error||!m||m.status==='completed'||m.status==='cancelled')return;const a=!!m.fighter_a_id,b=!!m.fighter_b_id;if(a===b)return;if(!m.bracket_id)return;const winnerId=a?m.fighter_a_id:m.fighter_b_id,winnerName=a?m.fighter_a_name:m.fighter_b_name;const {error:upErr}=await db.from('matches').update({status:'completed',winner_id:winnerId,winner_name:winnerName,completed_at:new Date().toISOString()}).eq('id',m.id);if(upErr)return;if(m.next_match_id){const slot=m.next_slot==='B'?'b':'a';const payload=slot==='a'?{fighter_a_id:winnerId,fighter_a_name:winnerName}:{fighter_b_id:winnerId,fighter_b_name:winnerName};const {error:nextErr}=await db.from('matches').update(payload).eq('id',m.next_match_id);if(!nextErr)await maybeAutoBye(m.next_match_id)}}
async function addMatch(){const a=athletes.find(x=>x.id===$('a').value),b=athletes.find(x=>x.id===$('b').value),category=$('category').value.trim();if(!a||!b||a.id===b.id||!category){toast('Preencha a categoria e selecione dois atletas diferentes.');return}const genderIssue=adultMatchGenderIssue(a,b);if(genderIssue){toast(genderIssue);return}const {error}=await db.from('matches').insert({category,mat:Number($('mat').value),fighter_a_id:a.id,fighter_b_id:b.id,fighter_a_name:a.display_name,fighter_b_name:b.display_name,status:'pending'});if(error)toast(error.message);else{$('category').value='';toast('Combate adicionado à fila');await load()}}
async function importPreparedBrackets(){
 const btn=$('importPreparedBrackets'),msg=$('preparedBracketsMsg');
 if(!db){toast('Ligue-se à cloud antes de importar.');return}
 const oldProposed=matches.filter(m=>String(m.match_code||'').startsWith('ICON-P-')||String(m.match_code||'').startsWith('ICON-R-'));
 if(oldProposed.some(m=>String(m.match_code||'').startsWith('ICON-R-')&&m.status!=='pending')){msg.textContent='Existem combates revistos já chamados, iniciados ou concluídos. Não os substituo para preservar resultados.';return}
 if(oldProposed.some(m=>m.status!=='pending')){msg.textContent='Existem combates propostos antigos que já foram chamados, iniciados ou concluídos. Não os substituo automaticamente para preservar resultados; anule/reveja esses combates antes de importar a distribuição revista.';return}
 const confirmText=`Importar os 42 emparelhamentos revistos (99 registos ativos; 3 repetidos exatos excluídos)?${oldProposed.length?` Serão substituídos ${oldProposed.length} combates ICON-P antigos que ainda estão pendentes.`:''}\n\nA lista procura incluir todos os atletas únicos e impedir confrontos do atleta contra si próprio. Nomes por confirmar e categorias mistas devem ser revistos.`;
 if(!confirm(confirmText))return;
 btn.disabled=true;msg.textContent='A associar atletas e a validar confrontos…';
 try{
  const response=await fetch('proposed_brackets.json',{cache:'no-store'});
  if(!response.ok)throw new Error('Não foi possível carregar proposed_brackets.json. Publique este ficheiro na mesma pasta da aplicação.');
  const proposals=await response.json();
  const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9@.]+/g,' ').trim();
  const resolveAthlete=(name,email)=>{
    const n=norm(name), e=norm(email);
    // Prefer exact athlete name. A shared family email must never select the first person.
    const byName=athletes.filter(a=>norm(a.display_name)===n);
    if(byName.length===1)return byName[0];
    if(byName.length>1)return null;
    const byEmail=e?athletes.filter(a=>norm(a.email)===e||norm(a.display_name)===e):[];
    return byEmail.length===1?byEmail[0]:null;
  };
  const payload=[], issues=[];
  for(const p of proposals){
    const a=resolveAthlete(p.fighter_a_name,p.fighter_a_email), b=resolveAthlete(p.fighter_b_name,p.fighter_b_email);
    if(a&&b&&a.id===b.id){issues.push(`Combate ${p.match_no}: o mesmo atleta foi associado aos dois lados`);continue}
    if(a&&b){const genderIssue=adultMatchGenderIssue(a,b);if(genderIssue){issues.push(`Combate ${p.match_no}: ${genderIssue}`);continue}}
    if(!a||!b)issues.push(`Combate ${p.match_no}: ${!a?'A':'B'} por associar (${!a?p.fighter_a_name:p.fighter_b_name})`);
    payload.push({match_code:`ICON-R-${String(p.match_no).padStart(3,'0')}`,category:p.category,mat:((p.match_no-1)%2)+1,fighter_a_id:a?.id||null,fighter_b_id:b?.id||null,fighter_a_name:a?.display_name||p.fighter_a_name,fighter_b_name:b?.display_name||p.fighter_b_name,status:'pending',bracket_id:null,round_number:1});
  }
  if(issues.length&&!confirm(`${issues.length} aviso(s) de associação foram detetados. Nenhum confronto associa intencionalmente um atleta a si próprio. Continuar a importar os confrontos, deixando os atletas ambíguos para correção manual?\n\n${issues.slice(0,8).join('\n')}${issues.length>8?'\n…':''}`)){msg.textContent='Importação cancelada para rever associações.';return}
  for(let i=0;i<payload.length;i+=20){const {error}=await db.from('matches').insert(payload.slice(i,i+20));if(error)throw error}
  if(oldProposed.length){const {error:deleteError}=await db.from('matches').delete().in('id',oldProposed.map(m=>m.id));if(deleteError)throw new Error('Os novos combates foram importados, mas os antigos não puderam ser removidos: '+deleteError.message)}
  msg.textContent=`Importação concluída: ${payload.length} combates pendentes. ${issues.length} aviso(s) para associação manual. Foram carregadas 42 propostas; 3 registos repetidos exatos foram excluídos e 15 atletas ficaram sem par ou a necessitar de revisão.`;
  toast(`${payload.length} combates importados.`);await load();
 }catch(e){msg.textContent='Falha na importação: '+e.message;toast('Não foi possível importar as chaves: '+e.message)}
 finally{btn.disabled=false}
}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const sep=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';return lines.map(line=>{let out=[],field='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quoted&&line[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){out.push(field.trim());field=''}else field+=c}out.push(field.trim());return out})}
function findCol(headers,terms){return headers.findIndex(x=>terms.some(s=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())))}
async function importCSV(file){try{const rows=parseCSV(await file.text()),headers=rows.shift()||[];const ix={email:findCol(headers,['email','e-mail','correio eletronico']),name:findCol(headers,['nome completo','nome do atleta','nome']),team:findCol(headers,['escola','equipa','academia','clube']),belt:findCol(headers,['faixa','graduacao','cinto']),age:findCol(headers,['idade','data de nascimento']),weight:findCol(headers,['peso','categoria de peso']),gender:findCol(headers,['sexo','genero','género','gender'])};if(ix.name<0){toast('Não encontrei a coluna do nome do atleta. Confirme os cabeçalhos do CSV.');return}let added=0,updated=0,skipped=0,errors=0;for(const r of rows){const val=i=>i>=0?(r[i]||'').trim():'';const email=val(ix.email);let name=correctedName(email,val(ix.name));if(!name){skipped++;continue}const sameEmail=athletes.filter(a=>email&&String(a.email||'').toLowerCase()===email.toLowerCase());const old=athletes.find(a=>a.display_name.trim().toLowerCase()===name.toLowerCase())||(sameEmail.length===1?sameEmail[0]:null);const d={display_name:name,email:email||null,team:val(ix.team),belt:val(ix.belt),age_text:normalizeAge(val(ix.age)),weight_text:normalizeWeight(val(ix.weight)),gender:normalizeGender(val(ix.gender))||null};let res;if(old){res=await db.from('athletes').update(d).eq('id',old.id);if(!res.error)updated++}else{res=await db.from('athletes').insert(d);if(!res.error)added++}if(res?.error)errors++}toast(`Importação concluída: ${added} novos, ${updated} atualizados, ${skipped} ignorados${errors?`, ${errors} erros`:''}. Reveja possíveis duplicados.`);await load()}catch(e){toast('Erro ao ler o CSV: '+e.message)}}
function renderPicker(){const chosen=new Set([...document.querySelectorAll('.athlete-choice:checked')].map(x=>x.value));const q=athletes.map(a=>`<div class="pick-row"><input class="athlete-choice" type="checkbox" value="${a.id}" ${chosen.has(a.id)?'checked':''} onchange="updateSelectedCount()"><span><button type="button" class="athlete-link athlete-name-link" onclick="openAthleteCategory('${a.id}')">${esc(a.display_name)}</button><small>${esc([a.belt,a.age_text,a.weight_text,a.gender==='M'?'Masculino':a.gender==='F'?'Feminino':'',a.team].filter(Boolean).join(' · ')||'Sem dados de categoria')}</small></span></div>`).join('');$('bracketAthletes').innerHTML=q||'<p class="empty-state">Importe atletas para começar a construir os quadros.</p>';updateSelectedCount()}
function updateSelectedCount(){const n=document.querySelectorAll('.athlete-choice:checked').length;$('selectedCount').textContent=`${n} atleta${n===1?'':'s'} selecionado${n===1?'':'s'}`}
function renderBracketOptions(){const sel=$('bracketView'),old=sel.value;const cats=[...new Set(matches.filter(m=>m.bracket_id).map(m=>m.category))];sel.innerHTML='<option value="all">Todas as categorias</option>'+cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(cats.includes(old))sel.value=old;renderBoards()}
function renderBoards(){if(!$('bracketBoards'))return;const filter=$('bracketView').value;const grouped=new Map();matches.filter(m=>m.bracket_id&& (filter==='all'||m.category===filter)).forEach(m=>{if(!grouped.has(m.bracket_id))grouped.set(m.bracket_id,{category:m.category,matches:[]});grouped.get(m.bracket_id).matches.push(m)});if(!grouped.size){$('bracketBoards').innerHTML='<p class="empty-state">Ainda não existem quadros automáticos. Selecione atletas e gere uma categoria acima.</p>';return}$('bracketBoards').innerHTML=[...grouped.entries()].map(([bid,g])=>{const rounds=new Map();g.matches.forEach(m=>{const r=m.round_number||1;if(!rounds.has(r))rounds.set(r,[]);rounds.get(r).push(m)});return `<div class="bracket-board"><h3>${esc(g.category)}</h3><div class="bracket-rounds">${[...rounds.entries()].sort((a,b)=>a[0]-b[0]).map(([r,ms])=>`<div class="round-column"><div class="round-label">${esc(roundName(r,Math.max(...rounds.keys())))}</div>${ms.sort((a,b)=>(a.match_code||'').localeCompare(b.match_code||'')).map(m=>`<div class="bracket-card"><div class="round-label">${esc(m.match_code||'Combate')}</div><div class="bracket-fighter ${m.status==='completed'&&m.winner_id===m.fighter_a_id?'winner':''}">${esc(m.fighter_a_name||'A aguardar atleta')} ${m.status==='completed'&&m.winner_id===m.fighter_a_id?'✓':''}</div><div class="bracket-fighter ${m.status==='completed'&&m.winner_id===m.fighter_b_id?'winner':''}">${esc(m.fighter_b_name||'A aguardar atleta')} ${m.status==='completed'&&m.winner_id===m.fighter_b_id?'✓':''}</div></div>`).join('')}</div>`).join('')}</div></div>`}).join('')}
function nextPowerOfTwo(n){let p=1;while(p<n)p*=2;return p}
function athleteWeightNumber(a){const v=String(a?.weight_text||'').replace(',','.').match(/[0-9]+(?:\.[0-9]+)?/);return v?Number(v[0]):null}
function athleteBracketCompatible(a,b){if(!a||!b||a.id===b.id)return false;if(ageGroup(a.age_text)!==ageGroup(b.age_text))return false;if(String(a.belt||'').trim().toLowerCase()!==String(b.belt||'').trim().toLowerCase())return false;if(isAdultAthlete(a)||isAdultAthlete(b)){if(!isAdultAthlete(a)||!isAdultAthlete(b)||!normalizeGender(a.gender)||normalizeGender(a.gender)!==normalizeGender(b.gender))return false}const wa=athleteWeightNumber(a),wb=athleteWeightNumber(b);if(wa!==null&&wb!==null&&Math.abs(wa-wb)>(isAdultAthlete(a)?12:8))return false;return true}
async function autoPrepareBracket(athleteId){const athlete=athletes.find(a=>a.id===athleteId);if(!athlete)return;const already=new Set(matches.filter(m=>m.bracket_id).flatMap(m=>[m.fighter_a_id,m.fighter_b_id]).filter(Boolean));const candidates=athletes.filter(a=>!already.has(a.id)&&(a.id===athleteId||athleteBracketCompatible(athlete,a)));if(candidates.length<2){toast('Atleta guardado. Ainda não existem pelo menos dois atletas sem chave e compatíveis para gerar automaticamente um quadro.');document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='brackets'));document.querySelectorAll('.pane').forEach(x=>x.classList.toggle('hidden',x.id!=='brackets'));const box=$('bracketMsg');if(box)box.textContent='O atleta foi guardado, mas não foi criada chave: são necessários pelo menos dois atletas compatíveis ainda sem chave. Atribua mais inscrições ou gere o quadro manualmente.';return}document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab==='brackets'));document.querySelectorAll('.pane').forEach(x=>x.classList.toggle('hidden',x.id!=='brackets'));document.querySelectorAll('.athlete-choice').forEach(c=>c.checked=candidates.some(a=>a.id===c.value));updateSelectedCount();const gender=isAdultAthlete(athlete)?(normalizeGender(athlete.gender)==='F'?'Feminino':'Masculino'):'';const category=[ageGroup(athlete.age_text),athlete.belt||'Faixa por definir',gender].filter(Boolean).join(' · ');$('bracketCategory').value=category;$('bracketMsg').textContent=`Preparação automática: ${candidates.length} atletas compatíveis sem chave selecionados. Confirme para criar o quadro; os quadros existentes não serão alterados.`;$('bracketCategory').scrollIntoView({behavior:'smooth',block:'center'});toast('Atletas compatíveis selecionados. Confirme a criação da nova chave.')}

async function generateBracket(){const category=$('bracketCategory').value.trim();const selected=[...document.querySelectorAll('.athlete-choice:checked')].map(c=>athletes.find(a=>a.id===c.value)).filter(Boolean);if(!category){$('bracketMsg').textContent='Introduza o nome da categoria.';return}if(selected.length<2){$('bracketMsg').textContent='Selecione pelo menos dois atletas.';return}const adults=selected.filter(isAdultAthlete);if(adults.length){if(adults.length!==selected.length){$('bracketMsg').textContent='Não misture adultos (18+) com atletas menores no mesmo quadro.';return}const genders=new Set(adults.map(a=>normalizeGender(a.gender)));if(genders.has('')||genders.size!==1){$('bracketMsg').textContent='Para criar um quadro de adultos, todos os atletas têm de ter sexo registado e ser do mesmo sexo. Não serão criadas chaves mistas entre homens e mulheres.';return}}if(!confirm(`Gerar quadro de eliminação direta para ${category} com ${selected.length} atletas? Serão criados combates novos; não se altera nenhum combate existente.`))return;$('generateBracket').disabled=true;$('bracketMsg').textContent='A gerar quadro…';try{const bracketId=crypto.randomUUID();const size=nextPowerOfTwo(selected.length);const rounds=Math.log2(size);const slots=[...selected];while(slots.length<size)slots.push(null);const all=[];for(let r=1;r<=rounds;r++){const count=size/Math.pow(2,r);const round=[];for(let i=0;i<count;i++)round.push({id:crypto.randomUUID(),round_number:r,match_code:`${bracketId.slice(0,4).toUpperCase()}-R${r}-${String(i+1).padStart(2,'0')}`,category,bracket_id:bracketId,mat:0,fighter_a_id:null,fighter_b_id:null,fighter_a_name:'A aguardar atleta',fighter_b_name:'A aguardar atleta',status:'pending',winner_id:null,winner_name:null,next_match_id:null,next_slot:null});all.push(round)}
// Round 1: distribute first available competitors in pairs. Byes are represented by one populated slot and one empty slot.
for(let i=0;i<all[0].length;i++){const a=slots[i*2]||null,b=slots[i*2+1]||null;all[0][i].fighter_a_id=a?.id||null;all[0][i].fighter_a_name=a?.display_name||'A aguardar atleta';all[0][i].fighter_b_id=b?.id||null;all[0][i].fighter_b_name=b?.display_name||'A aguardar atleta';if(a&&!b){all[0][i].status='completed';all[0][i].winner_id=a.id;all[0][i].winner_name=a.display_name;all[0][i].completed_at=new Date().toISOString()}else if(!a&&!b){all[0][i].status='cancelled'}}
for(let r=0;r<all.length-1;r++){for(let i=0;i<all[r].length;i++){all[r][i].next_match_id=all[r+1][Math.floor(i/2)].id;all[r][i].next_slot=i%2===0?'a':'b'}}
// Mat selection: alternate between tatames if requested.
const startMat=Number($('bracketMat').value);for(const round of all)for(let i=0;i<round.length;i++)round[i].mat=startMat===0?(i%2)+1:(startMat===1?1:2);
// Insert final rounds first so self-referential next_match_id foreign keys already exist.
for(let r=all.length-1;r>=0;r--){const {error}=await db.from('matches').insert(all[r]);if(error)throw error}
// Move first-round bye winners forward; automatically resolve any following byes where only one athlete can advance.
for(const m of all[0]){if(m.status==='completed'&&m.next_match_id){const slot=m.next_slot==='b'?'b':'a';const payload=slot==='a'?{fighter_a_id:m.winner_id,fighter_a_name:m.winner_name}:{fighter_b_id:m.winner_id,fighter_b_name:m.winner_name};const {error}=await db.from('matches').update(payload).eq('id',m.next_match_id);if(error)throw error}}
// Cascade byes in later rounds when exactly one feeder has an athlete and all feeders for the empty slot are settled.
for(let r=1;r<all.length;r++){for(const m of all[r]){const a=!!m.fighter_a_id,b=!!m.fighter_b_id;if(a!==b){const winnerId=a?m.fighter_a_id:m.fighter_b_id,winnerName=a?m.fighter_a_name:m.fighter_b_name;const {error}=await db.from('matches').update({status:'completed',winner_id:winnerId,winner_name:winnerName,completed_at:new Date().toISOString()}).eq('id',m.id);if(error)throw error;if(m.next_match_id){const slot=m.next_slot==='b'?'b':'a';const payload=slot==='a'?{fighter_a_id:winnerId,fighter_a_name:winnerName}:{fighter_b_id:winnerId,fighter_b_name:winnerName};const up=await db.from('matches').update(payload).eq('id',m.next_match_id);if(up.error)throw up.error}}}}
$('bracketMsg').textContent=`Quadro criado com ${selected.length} atletas e ${all.reduce((n,r)=>n+r.length,0)} posições de combate. Reveja as rondas e os byes.`;toast('Quadro eliminatório criado.');await load();$('bracketCategory').value='';}catch(e){$('bracketMsg').textContent='Não foi possível criar o quadro: '+e.message+'. Confirme se executou o ficheiro upgrade.sql no Supabase.';toast('Erro ao gerar quadro. Consulte a mensagem no formulário.')}finally{$('generateBracket').disabled=false}}
